                        if not math.isfinite(value):
                            raise ValueError(
                                "div backward intermediate must be finite"
                            )
                        da.append(value)
                    contributions.append((parent_self, da))
                else:
                    # A broadcast scalar parent reduces by accumulating
                    # from 0.0 in ascending output-index order.
